import copy
import json

from api import list_artifacts_response

cases = [
    [
        {"id": "report-a", "title": "Новый отчёт", "media_type": "application/pdf", "revision": 7, "byte_length": 0},
        {"id": "image-b", "title": "Preview", "media_type": "image/png", "revision": 1, "byte_length": 8193},
    ],
    [
        {"id": "notes-c", "title": 'Notes: "v2"\nDraft', "media_type": "text/plain", "revision": 31, "byte_length": 123},
        {"id": "report-a", "title": "Updated title", "media_type": "application/json", "revision": 8, "byte_length": 65537},
    ],
    [],
]
for records in cases:
    original = copy.deepcopy(records)
    status, body = list_artifacts_response(records)
    assert type(status) is int and status == 200, (status, body)
    assert isinstance(body, str), "The public boundary must return serialized JSON."
    payload = json.loads(body)
    expected = {
        "data": {
            "artifacts": [
                {
                    "id": row["id"],
                    "title": row["title"],
                    "metadata": {
                        "media_type": row["media_type"],
                        "byte_length": row["byte_length"],
                        "revision": row["revision"],
                    },
                }
                for row in original
            ],
        },
    }
    assert payload == expected, (payload, expected)
    for artifact in payload["data"]["artifacts"]:
        for field in ("byte_length", "revision"):
            value = artifact["metadata"][field]
            assert type(value) is int, (field, value)
    assert records == original, "Response serialization mutated source records."
